// js/data.js — Repositorio de Insights de Experiencia Digital
// Politécnico Grancolombiano · Dirección de Experiencia e Inclusión
// Versión 2.0 · Julio 2026
//
// Esquema de cada insight:
//  id            Código del insight (INS-XXX)
//  prioridad     Índice de prioridad (aún no asignado para ningún insight; se
//                deja el campo listo para completarlo más adelante)
//  nombre        Insight (síntesis del hallazgo)
//  tipo          Tipo (por ahora todos son "Insight")
//  tema          Tema al que pertenece el hallazgo
//  momento       Punto del journey en el que ocurre
//  estado        Estado del insight (p. ej. "Confirmado")
//  descripcion   Qué ocurre
//  impacto       Impacto en el estudiante
//  solucion      Alternativas de solución
//  fuentes       Fuentes de evidencia (no todas están documentadas todavía;
//                se deja el campo listo para completarlo más adelante)
//  propietario   Responsable de la solución
//  esfuerzo      Esfuerzo estimado

const insights = [
  { id:"INS-001", prioridad:"3", nombre:"La Universidad gestiona la experiencia a partir de las quejas, mientras una parte importante de las fricciones nunca llega a hacerse visible.", tipo:"Insight", tema:"Gestión de la experiencia", momento:"Transversal", estado:"Confirmado", descripcion:"La Universidad gestiona la experiencia principalmente a partir de las quejas, solicitudes y casos que los estudiantes reportan. Las fricciones que no generan un contacto con soporte o una PQRS permanecen invisibles y, por tanto, rara vez se convierten en oportunidades de mejora estructural.", impacto:"Los problemas que no se reportan permanecen sin resolverse, por lo que las mismas fricciones se repiten cada vez que el estudiante atraviesa el proceso. Cuando encuentra un obstáculo, con frecuencia debe recurrir a otros canales —como llamadas, chat, correo o atención presencial— para obtener respuestas y poder cumplir su objetivo.", solucion:"Complementar la gestión reactiva con mecanismos permanentes de escucha y observación de la experiencia, como investigación con usuarios, analítica de comportamiento, monitoreo de journeys, pruebas de usabilidad e indicadores de experiencia.", fuentes:"Tracker_Stakeholders_Experiencia_Digital: hallazgo general \"Modelo de servicio reactivo\" (\"Todo depende de que el usuario reporte un ticket. Los problemas no reportados no existen para el sistema\"). Reseñas de Google (Outscraper, 3 sedes, N=1.501 reseñas, 450 con texto): 43 reseñas (de las cuales 33 son de 1-2 estrellas) mencionan explícitamente haber recurrido a un canal alterno (llamada, WhatsApp, correo, presencial) para resolver algo que el canal digital no resolvió. Formulario_web (N=3.509): el 36,0% (1.262) respondió \"No\" a \"¿Dimos respuesta a tu solicitud?\", evidenciando fricciones que sólo se conocen porque el estudiante decidió volver a contactar.", propietario:"Áreas propietarias de los servicios y procesos digitales, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-002", prioridad:"2", nombre:"La gestión de la experiencia digital es reactiva: resuelve problemas a través del soporte en lugar de prevenirlos desde el diseño.", tipo:"Insight", tema:"Diseño de la experiencia", momento:"Transversal", estado:"Confirmado", descripcion:"La mayoría de las acciones para mejorar la experiencia digital se activan cuando el estudiante ya encontró un problema y solicita ayuda. La organización dispone de múltiples mecanismos de soporte y atención, pero existen pocos mecanismos orientados a prevenir las fricciones desde el diseño de plataformas, procesos y servicios.", impacto:"El estudiante depende, en demasiadas ocasiones, del soporte para completar tareas que debería poder resolver de manera autónoma. Los errores solo se hacen visibles cuando ya ocurrieron y las ayudas llegan cuando la fricción ya afectó la experiencia.", solucion:"Incorporar mecanismos que permitan anticipar y prevenir las fricciones antes de que afecten al estudiante, mediante investigación con usuarios, validaciones de experiencia, pruebas de usabilidad y accesibilidad, y evaluaciones previas a la implementación. Diseñar servicios, procesos y plataformas que orienten al estudiante en cada paso, prevengan errores frecuentes y ofrezcan ayudas contextuales y rutas de recuperación oportunas, reduciendo la dependencia del soporte para completar sus objetivos.", fuentes:"Tracker_Stakeholders_Experiencia_Digital: hallazgo general \"Modelo de servicio reactivo\" y entrevista con Wilson Leonardo Sánchez Angarita (UX), quien señala que UX \"no participa en priorización\" y solo levanta requerimientos ya identificados. No_rematriculados (N=3.908): de los 1.621 estudiantes que sí comunicaron su intención de no continuar (822 + 491, preguntas P8), el 81,0% (1.313) declara que no recibió alternativas efectivas para continuar, evidenciando que la intervención llega, cuando llega, después del hecho consumado.", propietario:"Áreas propietarias de los servicios y procesos digitales, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-003", prioridad:"15", nombre:"El estudiante vive una experiencia digital fragmentada y debe aprender qué plataforma o área resuelve cada necesidad, en lugar de encontrar una experiencia organizada alrededor de sus objetivos y tareas.", tipo:"Insight", tema:"Integración de la experiencia", momento:"Transversal", estado:"Confirmado", descripcion:"El estudiante debe comprender cómo está organizada la Universidad para alcanzar sus objetivos. Debe identificar qué plataforma utilizar, qué área es responsable de cada necesidad y cómo navegar entre múltiples sistemas que funcionan de manera independiente, en lugar de encontrar una experiencia integrada alrededor de sus tareas y objetivos.", impacto:"El estudiante invierte tiempo y esfuerzo en entender el funcionamiento interno de la Universidad antes de poder resolver su necesidad. La fragmentación genera incertidumbre, aumenta la probabilidad de errores y obliga a cambiar constantemente de plataforma, canal o área durante un mismo proceso.", solucion:"Diseñar la experiencia alrededor de los objetivos del estudiante y no de la estructura organizacional. Integrar plataformas, procesos y canales mediante recorridos coherentes, navegación consistente y transiciones claras entre servicios, de manera que el estudiante perciba una sola Universidad independientemente del área responsable.", fuentes:"Tracker_Stakeholders_Experiencia_Digital: hallazgos generales \"Ausencia de dueño de experiencia end-to-end\" (\"La responsabilidad está fragmentada por áreas. Cada una resuelve su parte pero nadie mira el recorrido completo\") y \"Las interacciones no suelen obedecer a las preguntas, tareas por hacer o patrones mentales de los usuarios, sino a la lógica de los distintos sistemas o plataformas\". Evidencia cualitativa (entrevistas a stakeholders); no se identificó una pregunta de encuesta que mida directamente la fragmentación percibida, lo cual es en sí mismo una oportunidad de instrumentación.", propietario:"Áreas propietarias de los servicios y procesos digitales, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-004", prioridad:"13", nombre:"La ausencia de un onboarding consistente y de ayudas contextuales obliga a los estudiantes a descubrir por sí mismos qué plataforma usar, dónde encontrar las funcionalidades, cómo utilizarlas y a qué área acudir.", tipo:"Insight", tema:"Onboarding y orientación", momento:"Incorporación (con impacto transversal)", estado:"Confirmado", descripcion:"La Universidad ofrece espacios de inducción, capacitaciones, tutoriales y otros mecanismos de orientación. Sin embargo, estas ayudas no siempre acompañan al estudiante en el momento y contexto en que las necesita. Al realizar una tarea, las ayudas contextuales y el onboarding resultan insuficientes, por lo que el estudiante debe descubrir por sí mismo qué plataforma utilizar, dónde encontrar las funcionalidades, cómo completar el proceso y a qué área acudir si encuentra dificultades.", impacto:"El estudiante debe recordar información recibida tiempo atrás o buscarla nuevamente cuando necesita realizar una tarea. Ante la falta de orientación en el momento y contexto adecuados, recurre al ensayo y error o a terceros para poder avanzar, aumentando la probabilidad de cometer errores, interrumpir el proceso o abandonar temporalmente la tarea.", solucion:"Complementar los mecanismos actuales de orientación con ayudas integradas a la experiencia digital, mediante recorridos guiados, instrucciones contextuales, mensajes oportunos y contenido adaptado al momento, la plataforma y la tarea que el estudiante está realizando. Diseñar un modelo institucional de onboarding que acompañe al estudiante durante los principales hitos de su journey, reduciendo la necesidad de recordar capacitaciones previas o buscar ayuda en otros canales.", fuentes:"Tracker_Stakeholders_Experiencia_Digital: mencionado de forma independiente por al menos 4 stakeholders — Carlos Eduardo Guzmán (\"Ausencia de onboarding en Canvas: no hay acompañamiento claro para que un estudiante empiece un curso\"), Luis Martín Trujillo (\"Ausencia de onboarding: no hay un proceso claro que guíe al estudiante nuevo en el uso de las plataformas\"), Adriana Alarcón Torres (sobre el formulario web) y Carlos Mauricio González (sobre Smart Campus). No_rematriculados (N=3.908): dentro de los 280 estudiantes que citan \"Soporte Institucional\" como motivo de no continuidad, 68 señalan puntualmente \"Falta de acompañamiento en el proceso de rematrícula\". Bienvenidas (N=1.664): la satisfacción con el evento de bienvenida es alta (medias entre 4,1 y 4,9/5), lo que sugiere que la falla no está en el evento de inducción puntual sino en el acompañamiento continuo dentro de las plataformas.", propietario:"Áreas propietarias de los servicios y procesos digitales, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-005", prioridad:"6", nombre:"Los trámites son momentos críticos de la experiencia. Cuando no se hace visible el estado del proceso, no se comunican oportunamente los cambios o no se cumplen los tiempos, se genera incertidumbre y el estudiante debe buscar respuestas en otras personas o canales para poder continuar.", tipo:"Insight", tema:"Diseño de la experiencia", momento:"Trámites y procesos", estado:"Confirmado", descripcion:"En los trámites y otros procesos que se desarrollan a lo largo del tiempo, la experiencia digital no siempre hace visible el estado del proceso, comunica oportunamente los cambios o informa con claridad los tiempos esperados. Como consecuencia, el estudiante debe recurrir a otros canales o personas para conocer qué está ocurriendo y cómo continuar.", impacto:"El estudiante no sabe con certeza si su solicitud, trámite o acción fue completada correctamente, qué está ocurriendo durante el proceso o qué debe hacer para continuar. Cuando la resolución no es inmediata, tampoco tiene claridad sobre cuándo obtendrá una respuesta o se resolverá su necesidad. Esta falta de visibilidad genera incertidumbre, disminuye la confianza en la experiencia y lo lleva a buscar respuestas en otros canales o personas.", solucion:"Mapear y diseñar los procesos desde la perspectiva del estudiante, identificando sus etapas, decisiones, posibles excepciones y puntos críticos. A partir de ello, hacer visibles las confirmaciones, el estado del proceso, el progreso, los tiempos estimados, los cambios relevantes y los siguientes pasos. Incorporar mecanismos de seguimiento y notificaciones oportunas que permitan comprender qué está ocurriendo, qué se espera del estudiante y cuándo puede esperar una respuesta o resultado, reduciendo la incertidumbre y la necesidad de acudir a otros canales o personas.", fuentes:"Certificados_20260625 (N=302): el 60,3% calificó como difícil (1-2 de 5) la facilidad general para solicitar un certificado (media 2,42/5); el 29,1% no tuvo claridad sobre los tiempos estimados de entrega y el 36,4% calificó mal la descarga del certificado tras el pago. Formulario_web (N=3.509): 36,0% no recibió respuesta a su solicitud y 23,5% calificó negativamente el \"tiempo para resolución y respuesta\".", propietario:"Áreas propietarias de los procesos y servicios digitales, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-006", prioridad:"20", nombre:"Con frecuencia, la comunicación se utiliza para compensar deficiencias en el diseño de la experiencia de servicios y procesos digitales.", tipo:"Insight", tema:"Comunicación institucional y diseño de servicio", momento:"Transversal", estado:"Confirmado", descripcion:"Cuando un proceso o plataforma falla o no es suficientemente claro, la respuesta suele ser aumentar la comunicación (llamadas, mensajes, notificaciones, guías o tutoriales) en lugar de mejorar el diseño del servicio, el proceso o la experiencia. En distintos puntos del journey se evidencian oportunidades para fortalecer la autogestión, las ayudas contextuales, los mensajes orientadores y el análisis del comportamiento de los estudiantes.", impacto:"El estudiante debe depender de información externa para comprender y completar tareas que la propia experiencia debería permitir resolver de manera autónoma. Cuando esa comunicación no está disponible, llega tarde o no responde a la situación específica que está viviendo, aumentan la confusión, los errores, la dependencia de otros canales y el esfuerzo necesario para alcanzar su objetivo.", solucion:"Priorizar el rediseño de los servicios y procesos antes de generar nuevas comunicaciones. Diseñar experiencias que permitan al estudiante comprender y completar sus tareas de forma autónoma, incorporando ayudas contextuales, mensajes orientadores, mecanismos de recuperación, analítica del comportamiento y capacidades de autogestión. Utilizar la comunicación para complementar la experiencia, no para compensar deficiencias en su diseño.", fuentes:"Patrón transversal inferido de los hallazgos anteriores (INS-001, INS-002, INS-004): no se identificó una pregunta de encuesta que mida directamente este patrón meta-organizacional. Se sustenta en la recurrencia, en las entrevistas del Tracker_Stakeholders_Experiencia_Digital, de soluciones basadas en comunicación (correos, llamadas, campañas) frente a fallas de diseño ya documentadas (Certificados, Encuestas_inscripción, Formulario_web). Se recomienda instrumentar este patrón específicamente en próximas mediciones.", propietario:"Áreas propietarias de los servicios y procesos digitales, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-007", prioridad:"15", nombre:"Para el estudiante no existen plataformas, procesos o áreas independientes; existe una sola Universidad.", tipo:"Insight", tema:"Integración de la experiencia", momento:"Transversal", estado:"Confirmado", descripcion:"La experiencia digital está organizada alrededor de plataformas, áreas y procesos independientes, por lo que el estudiante debe comprender cómo funciona la estructura interna de la Universidad para alcanzar sus objetivos. Como consecuencia, necesita identificar qué canal utilizar, qué área es responsable, con qué persona comunicarse y cómo pasar de un servicio a otro para completar una misma tarea.", impacto:"El estudiante debe invertir tiempo y esfuerzo en comprender la organización interna de la Universidad en lugar de concentrarse en alcanzar su objetivo. La fragmentación genera recorridos innecesarios entre plataformas, áreas y canales, aumenta la probabilidad de errores y transmite la percepción de estar interactuando con varias instituciones, en lugar de una sola Universidad.", solucion:"Diseñar la experiencia a partir de los objetivos y tareas del estudiante, y no de la estructura organizacional de la Universidad. Integrar plataformas, procesos, contenidos y puntos de contacto para ofrecer recorridos continuos, con navegación, lenguaje e información consistentes, reduciendo la necesidad de que el estudiante comprenda cómo está organizada la institución para completar sus tareas.", fuentes:"Mismas fuentes que INS-003 (Tracker_Stakeholders_Experiencia_Digital, hallazgos \"Ausencia de dueño de experiencia end-to-end\" y \"las interacciones no obedecen a los patrones mentales del usuario\"), complementadas con reseñas de Google donde estudiantes describen tener que contactar a más de un canal/área (llamada + correo + presencial) para resolver una sola necesidad (subconjunto de las 43 reseñas identificadas en INS-001). Se recomienda tratar INS-003 e INS-007 como una misma línea de trabajo, ya que describen el mismo fenómeno desde dos ángulos.", propietario:"Todas las áreas propietarias de servicios, procesos y plataformas digitales, con articulación institucional y acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Muy alto" },
  { id:"INS-008", prioridad:"1", nombre:"La experiencia de matrícula e inscripción no está determinada por una única fricción, sino por la acumulación de restricciones operativas, desarticulación entre plataformas, información insuficiente y fallas técnicas que se manifiestan en un mismo momento del journey.", tipo:"Insight", tema:"Diseño de la experiencia", momento:"Matrícula e inscripción", estado:"Confirmado", descripcion:"La experiencia de matrícula e inscripción reúne, en uno de los momentos más importantes del journey del estudiante, restricciones operativas, desarticulación entre plataformas, información insuficiente, fallas técnicas y otros factores que afectan simultáneamente la consecución de su objetivo. En lugar de enfrentar una única dificultad, el estudiante debe resolver varias fricciones encadenadas para completar un proceso del que depende la continuidad de su experiencia académica.", impacto:"El estudiante experimenta una alta carga cognitiva y emocional, ya que varias dificultades se presentan al mismo tiempo en un proceso del que depende la continuidad de sus estudios. La acumulación de fricciones incrementa el esfuerzo necesario para completar la matrícula o inscripción, aumenta la probabilidad de errores o de no alcanzar el resultado esperado y deteriora significativamente la percepción de la Universidad, incluso cuando cada problema, por separado, podría parecer menor.", solucion:"Diseñar y evaluar la experiencia de matrícula e inscripción como un journey estratégico de alto impacto, identificando la secuencia completa de tareas y la acumulación de fricciones que enfrenta el estudiante. Priorizar mejoras en los puntos donde convergen múltiples problemas y coordinar procesos, plataformas, contenidos y decisiones operativas para reducir el esfuerzo total, aumentar la confiabilidad del proceso y proteger uno de los momentos más relevantes de la experiencia estudiantil.", fuentes:"Convergencia de tres fuentes en la misma ventana del journey: Encuestas_inscripción (N=11.849) y Pago_matrícula (N=1.139, el 81,1% calificó como difícil gestionar el pago, media 1,73/5) muestran fricción simultánea en inscripción y pago; los comentarios abiertos de inscripción (11.724 comentarios) mencionan con más frecuencia \"horario/horarios\" (734), \"pago\" (190), \"cupo/cupos\" (333), \"asesor\" (124) y fallas técnicas (\"error\" 96, \"caída/no carga\" 108), confirmando que varios tipos de fricción (cupos, horarios, pagos, plataforma) ocurren encadenados en el mismo momento y no de forma aislada.", propietario:"Áreas responsables del proceso de matrícula e inscripción y de las plataformas que lo soportan, con articulación institucional y acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Muy alto" },
  { id:"INS-009", prioridad:"9", nombre:"Los estudiantes que realizan por primera vez la inscripción de asignaturas enfrentan muchas más dificultades que quienes ya conocen el proceso, lo que sugiere que la experiencia depende en gran medida del aprendizaje previo y evidencia oportunidades para fortalecer el onboarding de la plataforma y del proceso.", tipo:"Insight", tema:"Onboarding y orientación", momento:"Matrícula e inscripción", estado:"Confirmado", descripcion:"Los estudiantes que realizan por primera vez la inscripción de asignaturas enfrentan muchas más dificultades que quienes ya conocen el proceso. La experiencia exige comprender el funcionamiento de plataformas, reglas y procedimientos que no siempre se explican o acompañan en el momento en que se necesitan, por lo que el éxito depende en gran medida del aprendizaje previo.", impacto:"Los estudiantes de primer ingreso enfrentan una mayor carga cognitiva y emocional en uno de los momentos más importantes de su experiencia universitaria. La falta de familiaridad con el proceso aumenta la probabilidad de cometer errores, depender de otras personas para resolver dudas y no lograr el resultado esperado durante la inscripción de asignaturas.", solucion:"Diseñar un modelo de onboarding específico para la inscripción de asignaturas que acompañe al estudiante antes, durante y después de su primera experiencia con el proceso. Incorporar recorridos guiados, ayudas contextuales, simulaciones, mensajes oportunos y mecanismos de acompañamiento que reduzcan la dependencia del conocimiento previo y permitan completar la tarea con mayor autonomía y confianza.", fuentes:"Encuestas_inscripción20260625.xlsx (N=11.849, pregunta \"Califica el grado de esfuerzo que tuviste frente al proceso de inscripción de asignaturas\"): los estudiantes de 1er semestre reportan alto esfuerzo (calificación 4-5 de 5) en el 45,0% de los casos (N=542), frente a 18,6% entre estudiantes de 3er semestre en adelante (N=9.885) — una diferencia de 26,4 puntos porcentuales — y 26,0% entre estudiantes de 2do semestre (N=1.422).", propietario:"Áreas responsables del proceso de matrícula e inscripción y de las plataformas que lo soportan, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Medio - Alto" },
  { id:"INS-010", prioridad:"9", nombre:"Los estudiantes de modalidad presencial presentan significativamente más fricciones durante el proceso de inscripción de asignaturas que los estudiantes de modalidad virtual.", tipo:"Insight", tema:"Proceso transaccional / Inscripción de asignaturas", momento:"Matrícula e inscripción", estado:"Confirmado", descripcion:"Los estudiantes presenciales reportan significativamente más esfuerzo para completar la inscripción de asignaturas que los virtuales, además de menor claridad sobre fechas y requisitos del proceso, y fricciones más frecuentes con la disponibilidad de cupos, los cruces de horario y la validación de pagos.", impacto:"El estudiante presencial dedica más intentos y tiempo a completar su inscripción, enfrentando cupos agotados, cruces de horario y validaciones de pago que no reflejan a tiempo, aumentando la probabilidad de quedarse sin las asignaturas que necesita o de abandonar el intento temporalmente para volver a intentarlo.", solucion:"Profundizar en las causas específicas de la diferencia junto con Operaciones Académicas (¿es un tema de oferta de cupos, de cómo se comunica su disponibilidad, o de otra causa?). Del lado de experiencia digital, evaluar mejoras en la visualización de cruces de horario y en la validación en tiempo real del estado del pago frente a la matrícula.", fuentes:"Encuestas_inscripcion20260625.xlsx — encuesta \"Inscripción de asignaturas\" (N=11.848; presencial N=3.030, virtual N=8.818). Recálculo propio sobre la pregunta de esfuerzo confirma el hallazgo: 41,5% de los estudiantes presenciales reporta alto esfuerzo (4-5 de 5) frente a 13,6% de los virtuales — una diferencia de más de 3 veces. La media de esfuerzo también es más alta en presencial (3,14/5) que en virtual (2,08/5).", propietario:"Por definir", esfuerzo:"Medio" },
  { id:"INS-011", prioridad:"5", nombre:"La recurrencia de caídas de la plataforma y errores en el reconocimiento de los pagos durante la inscripción de asignaturas deteriora la confianza del estudiante en la experiencia digital.", tipo:"Insight", tema:"Confiabilidad", momento:"Matrícula e inscripción", estado:"Confirmado", descripcion:"Durante la inscripción de asignaturas se presentan de forma recurrente caídas de la plataforma y errores en el reconocimiento de los pagos. Al ocurrir en un momento crítico del journey, estas fallas interrumpen el proceso, generan incertidumbre sobre el estado de la transacción y afectan la percepción de confiabilidad de la experiencia digital.", impacto:"El estudiante no puede completar oportunamente la inscripción de asignaturas y debe interrumpir o repetir el proceso hasta lograr que la plataforma responda correctamente. Esto puede retrasar la inscripción, impedir el acceso a los cupos esperados y generar dependencia del soporte. La repetición de estas situaciones produce frustración y deteriora la confianza en la experiencia digital, especialmente en uno de los momentos más importantes de la vida académica.", solucion:"Fortalecer la estabilidad y el rendimiento de la plataforma durante los periodos de mayor demanda, garantizando la correcta integración con los sistemas de pago. Implementar mecanismos de monitoreo y alerta temprana que permitan detectar y resolver incidentes antes de que afecten masivamente a los estudiantes. Diseñar rutas de recuperación que permitan continuar el proceso sin perder información cuando ocurra una falla, e incorporar mensajes claros que informen el estado de la transacción y orienten al estudiante sobre los pasos a seguir.", fuentes:"Pago_matricula_20260625.xlsx (N=1.139): el 81,1% calificó como difícil (1-2 de 5) gestionar el pago de matrícula (media 1,73/5; distribución fuertemente concentrada en la calificación mínima: 695 de 1.138 respuestas), contrastando con calificaciones positivas (medias 4,1-4,4/5) en los aspectos de claridad de información, lo que apunta a una falla puntual de la transacción/plataforma más que de la información. Encuestas_inscripción: comentarios abiertos citan explícitamente \"la plataforma está fallando y tienen errores con el pago\", \"me da errores... cuando ya la había pagado\" y \"aparece como si no se hubiera pagado la matrícula\" (dentro de los 96 comentarios con \"error\" y 108 con \"caída/no carga\", de 11.724 comentarios).", propietario:"Áreas responsables de la plataforma de inscripción de asignaturas, la infraestructura tecnológica y la integración con los sistemas de pago, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-012", prioridad:"6", nombre:"Las restricciones de cupos y horarios son la principal fuente de fricción durante la inscripción de asignaturas, evidenciando una oportunidad para que la experiencia digital ayude al estudiante a anticiparlas, comprenderlas y gestionarlas mejor.", tipo:"Insight", tema:"Diseño de la experiencia", momento:"Matrícula e inscripción", estado:"Confirmado", descripcion:"La mayor parte de las quejas relacionadas con la inscripción de asignaturas corresponden a falta de cupos y choques de horario, por encima de las fallas técnicas de la plataforma. Aunque estas restricciones responden principalmente a decisiones académicas y operativas, la experiencia digital ofrece pocas herramientas para anticiparlas, comprenderlas o facilitar la toma de decisiones del estudiante durante el proceso.", impacto:"El estudiante no logra construir el horario que necesita y debe invertir tiempo adicional buscando alternativas, modificando su selección o solicitando apoyo para resolver restricciones que no comprende completamente. La inscripción deja de percibirse como un proceso que facilita el logro de su objetivo y se convierte en una experiencia de frustración, incertidumbre y pérdida de control.", solucion:"Diseñar una experiencia de inscripción que ayude al estudiante a anticipar y gestionar las restricciones de cupos y horarios mediante información clara, disponibilidad de cupos en tiempo real, advertencias tempranas sobre conflictos de horario, visualización de alternativas, recomendaciones de asignaturas y horarios, listas de espera cuando aplique y explicaciones comprensibles sobre las restricciones del proceso. Complementar estas acciones con el análisis conjunto de la evidencia para identificar oportunidades de mejora en la oferta académica y la planeación de horarios.", fuentes:"Encuestas_inscripción (N=11.849): \"horario\"/\"horarios\" son las palabras más repetidas en los 11.724 comentarios abiertos (734 menciones combinadas), seguidas de \"cupo\"/\"cupos\" (333 menciones); el aspecto \"Encontrar asignaturas con cupos disponibles\" recibe calificación negativa (1-2 de 5) en 33,3% de las respuestas (N=3.031) y \"Organizar tu horario\" en 34,8%. Comentarios ilustrativos: \"Deberían de abrir más cupos\", \"no dan opciones de horario para nada\", \"hay muchas personas... y se acaban muy rápido los cupos\".", propietario:"Áreas responsables de la planeación académica, matrícula e inscripción de asignaturas y de la plataforma de inscripción, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-013", prioridad:"19", nombre:"La experiencia en dispositivos móviles se percibe como inferior a la experiencia en computador, evidenciando oportunidades para fortalecer la experiencia móvil en los servicios y procesos digitales.", tipo:"Insight", tema:"Diseño de la experiencia", momento:"Transversal (uso de plataformas y servicios digitales)", estado:"Confirmado", descripcion:"Los estudiantes manifiestan que realizar tareas desde dispositivos móviles resulta más difícil que hacerlo desde un computador. Se reportan dificultades para navegar, visualizar información, completar procesos e interactuar con algunas funcionalidades, lo que sugiere que la experiencia móvil no responde de la misma manera a las necesidades de uso identificadas en otros dispositivos.", impacto:"El estudiante encuentra mayores dificultades para completar tareas cuando accede desde su dispositivo móvil, lo que puede obligarlo a posponer actividades, buscar un computador o invertir más tiempo para alcanzar el mismo objetivo. Esto reduce la flexibilidad que debería ofrecer la experiencia digital y genera frustración al no poder realizar gestiones académicas desde el dispositivo que tiene disponible en ese momento.", solucion:"Realizar una evaluación específica de la experiencia móvil mediante pruebas de usabilidad, analítica digital y retroalimentación de los estudiantes para identificar los principales puntos de fricción. Priorizar el diseño mobile-first en nuevos desarrollos y mejoras, optimizar los flujos de mayor uso, simplificar las interacciones, garantizar la correcta adaptación de los componentes a diferentes tamaños de pantalla y establecer indicadores que permitan monitorear de forma continua el desempeño de la experiencia en dispositivos móviles.", fuentes:"Encuestas_inscripción, cruce por tipo de dispositivo declarado (P: \"tipo de dispositivo que utilizaste\"): los estudiantes que usaron celular/smartphone (N=469) reportan alto esfuerzo en 23,5% de los casos, frente a 20,2%-21,2% en portátil/escritorio (N=6.601 y 4.420); en \"claridad del contenido informativo\", móvil tiene 18,6% de calificaciones negativas frente a 15,2% en portátil. La brecha es consistente pero moderada (3-5 puntos porcentuales), por lo que la evidencia cuantitativa disponible matiza —no descarta— el insight. Tracker_Stakeholders_Experiencia_Digital: Comunicaciones (Carolina Lara / Yenzy Fajardo) reporta \"fricciones con desarrollo\" porque, en sus palabras, \"no cumple con todos los estándares de mobile, accesibilidad\", lo que corrobora cualitativamente la brecha.", propietario:"Áreas responsables de las plataformas digitales y del diseño y desarrollo de productos digitales, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Medio - Alto" },
  { id:"INS-014", prioridad:"3", nombre:"La experiencia digital ofrece pocas rutas de recuperación; cuando un proceso falla o el estudiante se sale del camino previsto, la experiencia no explica qué ocurrió, por qué ocurrió ni cómo continuar.", tipo:"Insight", tema:"Diseño de la experiencia", momento:"Transversal", estado:"Confirmado", descripcion:"Cuando un proceso no puede completarse como estaba previsto, los estudiantes encuentran mensajes poco claros o inexistentes, carecen de orientación para entender qué sucedió y no reciben instrucciones sobre cómo continuar. En varios servicios digitales predominan mensajes de error técnicos, silencios del sistema o interrupciones del flujo sin mecanismos que faciliten la recuperación de la tarea.", impacto:"El estudiante no logra recuperar el proceso por sí mismo y debe detener la tarea, intentar nuevamente o buscar ayuda para poder continuar. Una dificultad puntual termina convirtiéndose en una interrupción del objetivo que quería alcanzar, aumentando la frustración, la dependencia del soporte y la percepción de que la experiencia digital no acompaña al usuario cuando más lo necesita.", solucion:"Incorporar estrategias de recuperación de errores como principio de diseño en todos los servicios digitales. Diseñar mensajes de error claros y orientados a la acción, explicar las causas cuando sea posible, indicar los pasos para continuar, permitir retomar procesos sin perder la información ya diligenciada e implementar ayudas contextuales adaptadas al momento específico en que ocurre la dificultad. Complementar estas acciones con el análisis de los errores más frecuentes para priorizar mejoras preventivas en los flujos de mayor impacto.", fuentes:"Encuestas_inscripción: comentarios como \"no me ha dejado inscribir materias... he estado toda la madrugada intentando... pero no me dicen nada al respecto\" ilustran la ausencia de explicación y ruta de recuperación (dentro de los ~200 comentarios que mencionan errores o caídas de plataforma, de 11.724). No_rematriculados (N=3.908): 113 estudiantes citan puntualmente \"Dificultades con respuesta a casos\" como motivo de soporte institucional. Formulario_web: 36,0% (1.262 de 3.509) no recibió respuesta a su solicitud, es decir, su caso no tuvo una ruta de cierre o recuperación visible.", propietario:"Áreas responsables del diseño, desarrollo y administración de las plataformas digitales, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Medio - Alto" },
  { id:"INS-015", prioridad:"13", nombre:"La información puede llegar cuando ya no hay posibilidad de actuar, por lo que se perciben más como explicaciones que herramientas para tomar decisiones.", tipo:"Insight", tema:"Información para la toma de decisiones", momento:"Transversal (momentos de decisión y ejecución de tareas)", estado:"Confirmado", descripcion:"En distintos momentos del journey, la información necesaria para tomar una decisión, completar una tarea o evitar una fricción aparece cuando el estudiante ya no puede actuar o modificar el resultado. Esto ocurre en mensajes del sistema, estados de procesos, ayudas contextuales, reglas de negocio, notificaciones y comunicaciones institucionales.", impacto:"El estudiante pierde oportunidades para actuar a tiempo y debe asumir las consecuencias de información que llegó demasiado tarde. Esto puede impedirle completar una tarea, obligarlo a repetir procesos o buscar alternativas que podrían haberse evitado. Como consecuencia, disminuye la percepción de acompañamiento y la información pierde valor como herramienta para tomar decisiones.", solucion:"Identificar los momentos de decisión de cada journey y asegurar que la información esté disponible antes de que el estudiante deba actuar. Diseñar mensajes, estados, ayudas, alertas y notificaciones que permitan anticipar restricciones, prevenir errores y orientar la toma de decisiones, revisando continuamente los puntos donde la información llega demasiado tarde.", fuentes:"Certificados (N=302): 29,1% de los estudiantes no tuvo claridad sobre los tiempos estimados de entrega, es decir, se enteran del plazo real sólo al vivir el proceso. Encuestas_inscripción: comentarios describen enterarse de un bloqueo de pago justo al momento de inscribir (\"no me deja inscribir materias me dice que no pague matrícula, pero soy becada\"), cuando ya no hay margen de reacción antes del cierre de inscripciones.", propietario:"Áreas responsables de los procesos y servicios digitales, de los contenidos y comunicaciones institucionales, y de las plataformas que soportan la experiencia, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Medio" },
  { id:"INS-016", prioridad:"20", nombre:"La información no siempre es consistente entre sus distintas fuentes, por lo que el estudiante puede actuar con expectativas que el proceso no cumple, deteriorando la confianza en la información institucional.", tipo:"Insight", tema:"Información para la toma de decisiones", momento:"Transversal (todos los servicios y procesos digitales)", estado:"Confirmado", descripcion:"En algunos procesos, el estudiante encuentra información diferente entre plataformas, páginas, correos, reglamentos u otras fuentes institucionales. En ocasiones la información está desactualizada, es incompleta o contradice la forma en que realmente funciona el proceso, dificultando que el estudiante actúe con seguridad.", impacto:"El estudiante invierte tiempo siguiendo indicaciones que no le permiten completar la tarea como esperaba y debe buscar nuevas fuentes de información, repetir pasos o solicitar ayuda para continuar. Cuando la experiencia contradice la información recibida, disminuye la confianza en la información institucional y aumenta la incertidumbre sobre cómo realizar correctamente el proceso.", solucion:"Establecer una única fuente oficial para la información de cada proceso y definir mecanismos de gobernanza que garanticen su actualización y consistencia en todos los canales. Revisar periódicamente los contenidos de mayor impacto para identificar contradicciones, información desactualizada o vacíos, e incorporar controles que eviten la publicación de versiones diferentes sobre un mismo proceso. Complementar estas acciones con una arquitectura de información que facilite identificar cuál es la información vigente y oficial.", fuentes:"No se identificó una pregunta de encuesta que mida directamente la consistencia de la información entre fuentes. Se infiere de forma indirecta a partir de casos como el de estudiantes becados a quienes la plataforma de inscripción indica que no han pagado matrícula (comentarios de Encuestas_inscripción), lo que sugiere desalineación entre la fuente de información de becas/pagos y la que consulta la plataforma de inscripción. Se recomienda instrumentar este patrón específicamente (por ejemplo, con una pregunta de encuesta o auditoría de contenidos).", propietario:"Áreas responsables de los procesos y de la información institucional, equipos de contenido y comunicaciones, administradores de las plataformas digitales y propietarios funcionales de cada servicio, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Medio - Alto" },
  { id:"INS-017", prioridad:"11", nombre:"El estudiante descubre problemas inesperados durante la inscripción de asignaturas cuando ya afectan su proceso, aunque la Universidad cuenta con información para anticiparse y orientarlo.", tipo:"Insight", tema:"Información para la toma de decisiones", momento:"Matrícula e inscripción", estado:"Confirmado", descripcion:"Durante la inscripción de asignaturas, la Universidad dispone de información que permite identificar situaciones como asignaturas que no se abrirán, cambios de horario, conflictos entre materias o alternativas equivalentes. Sin embargo, esta información no siempre se utiliza para anticiparse, orientar al estudiante o facilitar una decisión antes de que el problema afecte su proceso.", impacto:"El estudiante descubre problemas cuando ya afectan su inscripción y debe invertir tiempo en entender qué ocurrió, buscar alternativas o solicitar apoyo para resolver una situación que la Universidad podía anticipar. Esto puede retrasar la inscripción, limitar sus opciones académicas y generar frustración, además de disminuir la percepción de acompañamiento durante uno de los momentos más críticos de su experiencia.", solucion:"Implementar alertas proactivas cuando se identifiquen situaciones que afecten la inscripción del estudiante, como asignaturas que no se abrirán, choques de horario o restricciones para inscribir una materia. Acompañar estas alertas con explicaciones claras y alternativas de solución, como asignaturas equivalentes, horarios disponibles o los pasos para resolver la situación. Priorizar la automatización de estos casos utilizando la información que la Universidad ya conoce.", fuentes:"Encuestas_inscripción: comentarios recurrentes documentan bloqueos que la Universidad ya conocía pero no anticipó al estudiante, por ejemplo becas no reflejadas en el estado de pago (\"no me deja inscribir... soy becada... a varias compañeras le pasa lo mismo\") y materias sin cupos que se agotan sin aviso previo. Estos casos están contenidos dentro de los 190 comentarios que mencionan \"pago\" y los 333 que mencionan \"cupo/cupos\" (de 11.724 comentarios).", propietario:"Áreas responsables de matrícula e inscripción, registro académico, plataformas digitales y analítica institucional, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-018", prioridad:"24", nombre:"Los manuales y tutoriales se valoran cuando reflejan lo que está viviendo el estudiante, pero al ser genéricos y estáticos, cuando no coinciden con el paso, programa o pantalla exacta, pueden confundir, no ayudar y generar frustración.", tipo:"Insight", tema:"Ayuda y acompañamiento", momento:"Transversal (uso de plataformas y servicios digitales)", estado:"Confirmado", descripcion:"Los estudiantes valoran positivamente los manuales y tutoriales disponibles, pero con frecuencia estos fueron elaborados para escenarios generales y no reflejan exactamente el programa, el paso del proceso o la pantalla que están utilizando. Cuando existen diferencias entre la guía y la experiencia real, dejan de ser una ayuda efectiva y generan nuevas fricciones.", impacto:"El estudiante invierte tiempo intentando adaptar la guía a su situación, puede cometer errores o abandonar la ayuda al no encontrar correspondencia con lo que está viendo en pantalla. En lugar de facilitar la tarea, el apoyo disponible puede aumentar la confusión, la frustración y la dependencia de otros canales para resolver el problema.", solucion:"Complementar los manuales y tutoriales generales con ayudas contextuales integradas en las plataformas, mostrando la información adecuada según el programa, el paso del proceso y la pantalla en la que se encuentra el estudiante. Revisar periódicamente los contenidos para mantenerlos actualizados e incorporar mecanismos de retroalimentación que permitan identificar cuándo una guía deja de corresponder con la experiencia real.", fuentes:"No se identificó, dentro de los archivos entregados, una pregunta o comentario que mencione específicamente manuales o tutoriales genéricos. Es el insight con menor respaldo directo en la evidencia disponible; se recomienda validarlo con una pregunta específica en encuestas futuras o con pruebas de usabilidad dirigidas (por ejemplo, observar a un estudiante siguiendo un tutorial existente).", propietario:"Áreas responsables de los procesos y plataformas digitales, equipos de contenido y soporte, con acompañamiento metodológico de la Dirección de Experiencia e Inclusión.", esfuerzo:"Medio" },
  { id:"INS-019", prioridad:"22", nombre:"La accesibilidad todavía depende del criterio y conocimiento de quien crea el contenido, no de un sistema que la garantice de manera consistente.", tipo:"Insight", tema:"Accesibilidad digital", momento:"Transversal (todos los contenidos y servicios digitales)", estado:"Confirmado", descripcion:"La accesibilidad depende en gran medida de las decisiones que toma cada persona al crear contenidos o diseñar experiencias digitales. La ausencia de lineamientos, herramientas, controles y procesos comunes hace que la accesibilidad varíe entre plataformas, servicios y canales.", impacto:"Los estudiantes pueden encontrar barreras diferentes según la plataforma, el contenido o el servicio que utilicen, generando una experiencia inconsistente y, en algunos casos, impidiendo completar tareas de forma autónoma. Esto incrementa la dependencia de apoyos adicionales y reduce la percepción de inclusión y confiabilidad de la experiencia digital.", solucion:"Implementar un sistema de gestión de la accesibilidad que incluya lineamientos institucionales, componentes accesibles reutilizables, listas de verificación, revisiones periódicas, herramientas de validación automática y formación continua para los equipos que diseñan, desarrollan y publican contenidos. Incorporar criterios de accesibilidad como requisito antes de publicar nuevos productos, funcionalidades o contenidos digitales.", fuentes:"Tracker_Stakeholders_Experiencia_Digital: única mención directa a accesibilidad, del equipo de Comunicaciones (Carolina Lara / Yenzy Alexandra Fajardo Robelto), quien reporta \"fricciones con desarrollo\" porque, en sus palabras, \"no cumple con todos los estándares de mobile, accesibilidad\". No se encontró una fuente cuantitativa (encuesta o auditoría técnica) sobre accesibilidad en los archivos entregados; se recomienda una auditoría de accesibilidad (WCAG) como fuente de evidencia adicional.", propietario:"Dirección de Experiencia e Inclusión, equipos de Tecnología, Diseño, Comunicaciones y todas las áreas responsables de crear, publicar o mantener contenidos y servicios digitales.", esfuerzo:"Alto" },
  { id:"INS-020", prioridad:"12", nombre:"La atención varía naturalmente según quién la brinde, pero la información para resolver un mismo trámite debería ser consistente.", tipo:"Insight", tema:"Información para la toma de decisiones", momento:"Transversal (cuando el estudiante necesita orientación para completar una tarea)", estado:"Confirmado", descripcion:"Cuando el estudiante necesita orientación para completar un trámite, puede recibir respuestas diferentes según el canal o la persona consultada. Esto evidencia que la información que soporta la atención no siempre es consistente ni está integrada de forma uniforme en la experiencia digital.", impacto:"El estudiante debe consultar varios canales, validar la información recibida o repetir pasos hasta encontrar una respuesta que le permita continuar. Esto incrementa el esfuerzo necesario para completar la tarea y disminuye la confianza en la información disponible para realizar el trámite.", solucion:"Implementar una única fuente de información para cada trámite e integrarla a todos los canales digitales y de atención. Fortalecer el autoservicio mediante ayudas contextuales, bases de conocimiento y asistentes digitales que entreguen respuestas consistentes, reduciendo la necesidad de acudir a diferentes canales para obtener orientación.", fuentes:"Formulario_web (N=3.509): la satisfacción con la atención recibida muestra una distribución marcadamente bimodal (934 respuestas de 1/5 \"muy insatisfecho\" frente a 1.901 de 5/5 \"muy satisfecho\"), lo que sugiere una experiencia muy desigual según el caso o la persona que atendió, más que un problema homogéneo. No_rematriculados: dentro del motivo \"Soporte Institucional\" (280 casos), 47 citan mal servicio de atención online y 33 mal servicio de atención telefónica, evidenciando variabilidad por canal.", propietario:"Áreas responsables de los trámites institucionales, equipos responsables de las plataformas digitales, propietarios de la información de cada proceso y Dirección de Experiencia e Inclusión.", esfuerzo:"Medio - Alto" },
  { id:"INS-021", prioridad:"17", nombre:"Los contactos humanos casi siempre son amables y empáticos, pero no siempre logran comprender y resolver las necesidades del estudiante.", tipo:"Insight", tema:"Recuperación de la experiencia", momento:"Transversal (cuando el estudiante requiere apoyo para continuar un proceso digital)", estado:"Confirmado", descripcion:"Cuando el estudiante no logra completar una tarea y recurre a un canal de atención, suele recibir un trato amable y empático. Sin embargo, la interacción no siempre logra resolver su necesidad, por lo que debe volver a explicar su caso, acudir a otro canal o contactar a otra persona para continuar su proceso.", impacto:"El estudiante invierte más tiempo y esfuerzo para resolver una necesidad que esperaba solucionar desde el primer contacto. La repetición de la situación entre personas y canales prolonga el journey, genera frustración y reduce la percepción de que la Universidad puede acompañarlo eficazmente cuando la experiencia digital falla.", solucion:"Diseñar los canales de atención como mecanismos de recuperación de la experiencia digital. Proporcionar a los equipos de atención el contexto del estudiante y el estado de su trámite para evitar que deba repetir su caso. Incorporar trazabilidad entre canales y criterios de escalamiento que permitan dar continuidad al proceso y aumentar la resolución desde el primer contacto.", fuentes:"No_rematriculados (N=3.908): dentro del motivo \"Soporte Institucional\" (280 casos), 113 citan \"Dificultades con respuesta a casos\" (el trato no es el problema mencionado, sino la resolución). Reseñas de Google: 8 de 450 reseñas con texto mencionan explícitamente mala atención, un volumen bajo que es consistente con la lectura de que el trato humano no es, en general, el foco de la queja, sino la resolución efectiva.", propietario:"Equipos responsables de las plataformas digitales, áreas propietarias de los procesos institucionales, equipos de atención al estudiante y Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-022", prioridad:"6", nombre:"Los casos no resueltos se cierran, archivan o anulan en lugar de mantenerse abiertos, obligando al estudiante a reiniciar el trámite desde cero cada vez que vuelve a contactar a la Universidad.", tipo:"Insight", tema:"Gestión y continuidad de casos", momento:"Transversal", estado:"Confirmado", descripcion:"Cuando un trámite no se resuelve en el primer contacto, el caso puede cerrarse, archivarse o perder continuidad. Si el estudiante vuelve a contactar a la Universidad, con frecuencia debe explicar nuevamente la situación e iniciar el proceso como si fuera un caso nuevo.", impacto:"El estudiante debe reconstruir el contexto de su caso cada vez que retoma el trámite, repetir información y recorrer nuevamente el mismo proceso. Esto incrementa el esfuerzo necesario para alcanzar su objetivo, prolonga los tiempos de resolución y transmite la sensación de que la Universidad no recuerda ni da continuidad a su situación.", solucion:"Mantener abiertos los casos hasta su resolución o permitir su reactivación conservando el historial, el contexto y las gestiones realizadas. Incorporar trazabilidad entre canales y mecanismos que permitan retomar el trámite desde el punto en que quedó, sin obligar al estudiante a iniciar nuevamente el proceso.", fuentes:"Formulario_web (N=3.509): el 36,0% (1.262) responde \"No\" a \"¿Dimos respuesta a tu solicitud?\", es decir, más de un tercio de los casos no llegó a un cierre visible para el estudiante. No_rematriculados (N=3.908): de los 1.621 estudiantes que sí comunicaron su intención de no continuar, el 81,0% (1.313 = 822 + 491) declara no haber recibido alternativas efectivas — el caso quedó, en la práctica, sin continuidad ni seguimiento activo por parte de la Universidad.", propietario:"Equipos responsables de las plataformas de gestión de casos, áreas propietarias de los procesos institucionales, equipos de atención al estudiante y Dirección de Experiencia e Inclusión.", esfuerzo:"Alto" },
  { id:"INS-023", prioridad:"23", nombre:"Durante el proceso de grado, la experiencia digital no siempre orienta al estudiante con la claridad y anticipación que requiere este momento, ni refleja la importancia que tiene dentro de su experiencia con la Universidad.", tipo:"Insight", tema:"Acompañamiento en momentos críticos del journey", momento:"Proceso de grado", estado:"Confirmado", descripcion:"Durante el proceso de grado, los estudiantes manifiestan dificultades para comprender con claridad los pasos, requisitos, documentos, pagos y plazos necesarios para completar el proceso. Al mismo tiempo, perciben que la experiencia digital trata este momento como un trámite más, sin el nivel de acompañamiento y reconocimiento que esperan para el cierre de su vida académica.", impacto:"El estudiante debe invertir tiempo adicional para confirmar qué debe hacer, cuándo hacerlo y qué requisitos tiene pendientes, aumentando la incertidumbre en un momento de alta importancia personal. La falta de acompañamiento y reconocimiento hace que el cierre de la experiencia universitaria pierda parte del valor y significado que representa para el estudiante.", solucion:"Diseñar una experiencia de grado que combine acompañamiento funcional y reconocimiento del logro. Incorporar una lista personalizada de requisitos y pendientes, línea de tiempo del proceso, estado visible de documentos y pagos, recordatorios automáticos de los próximos hitos y ayudas contextuales. Complementar estos elementos con experiencias de reconocimiento como mensajes personalizados, contenidos de bienvenida a la comunidad de egresados y recursos digitales que conviertan el cierre del journey en un momento memorable.", fuentes:"Graduacion_20260625.xlsx (N=1.243): la satisfacción general con la ceremonia de grado es alta (medias entre 3,9 y 4,7 sobre 5, y una probabilidad de recomendación de 9,2/10 en la sub-muestra que respondió NPS), por lo que la encuesta disponible —centrada en la ceremonia, no en el trámite administrativo previo— no muestra fricción fuerte y matiza el insight. Los comentarios abiertos (N=772) mencionan \"diploma\"/\"acta\" 20 veces, apuntando a demoras puntuales en la entrega de documentos como el punto de fricción más concreto encontrado. Se recomienda instrumentar específicamente el trámite de grado (requisitos, paz y salvos, generación de acta) y no sólo la ceremonia, para sustentar mejor este insight.", propietario:"Registro y Control Académico, áreas responsables del proceso de grado, equipos responsables de las plataformas digitales, Comunicaciones, Relacionamiento con Egresados y Dirección de Experiencia e Inclusión.", esfuerzo:"Medio - Alto" },
  { id:"INS-024", prioridad:"18", nombre:"La analítica no es una práctica estandarizada entre las áreas que gestionan la experiencia digital: mientras algunas la usan de forma consistente para decidir, otras la aplican de forma parcial o reactiva, y otras aún no la incorporan en su proceso de trabajo.", tipo:"Insight", tema:"Cultura y capacidad de decisión basada en datos", momento:"Transversal", estado:"Confirmado", descripcion:"El uso de analítica varía según el área, pero en la mayoría de los casos los datos aún no se usan como herramienta para anticipar o prevenir fricciones: algunas áreas cuentan con tableros y cultura de medición consolidada, otras se apoyan solo en lo que reportan los tickets, y otras aún no tienen acceso o práctica propia de analítica de comportamiento.", impacto:"El estudiante enfrenta fricciones que la Universidad podría haber anticipado, pero que solo se identifican cuando ya lo afectaron y decidió reportarlas. Esto aumenta la probabilidad de que problemas ya vividos por otros estudiantes se repitan una y otra vez antes de convertirse en una mejora real.", solucion:"Usar las áreas con cultura de medición ya instalada como referencia interna. Formalizar el acceso a herramientas de analítica de comportamiento y datos crudos para las áreas que aún no lo tienen. Complementar el análisis de tickets con fuentes más proactivas, como consultas repetidas sin resolver, que permitan anticipar fricciones en lugar de solo reaccionar a ellas.", fuentes:"Tracker_Stakeholders_Experiencia_Digital — entrevistas con Wilson Leonardo Sánchez Angarita (UX/Desarrollo: \"UX no participa en priorización... solo levanta requerimientos\"), Carlos Eduardo Guzmán (Ambiente de Aprendizaje), Luis Martín Trujillo (CREA), Carlos Mauricio González (Smart Campus), Adriana Alarcón Torres (Servicio) y Giovanny Alexander Hidrobo Barrera (Mercadeo); hallazgo general \"Vacío de analítica de experiencia\" (\"No hay evidencia de herramientas de analítica cualitativa como mapas de calor, grabaciones de sesión o detección de clics fallidos\").", propietario:"Gerencia de Tecnología e Innovación Digital, Dirección de Experiencia e Inclusión, áreas propietarias de cada plataforma o proceso", esfuerzo:"Medio" }
];
